package io.github.ningpp.compat;

/** Replacement for Microsoft.PowerShell.Commands.WriteErrorException (generated by CSharpToJava converter). */
public class WriteErrorException extends SystemException {
    public WriteErrorException() { super(); }
    public WriteErrorException(String message) { super(message); }
    public WriteErrorException(String message, Throwable cause) { super(message, cause); }
}
